RenoirManagerHandle renoir_manager_create_with_control(const struct RenoirRegionConfig *config);

/**
 * Create a shared memory manager without control region
 */
RenoirManagerHandle renoir_manager_create(void);

/**
 * Destroy a shared memory manager
 */
enum RenoirErrorCode renoir_manager_destroy(RenoirManagerHandle handle);

/**
 * Create a shared memory region
 */
enum RenoirErrorCode renoir_region_create(RenoirManagerHandle manager,
                                          const struct RenoirRegionConfig *config,
                                          RenoirRegionHandle *region_handle);

/**
 * Get an existing shared memory region
 */
enum RenoirErrorCode renoir_region_get(RenoirManagerHandle manager,
                                       const char *name,
                                       RenoirRegionHandle *region_handle);

/**
 * Get region size
 */
uintptr_t renoir_region_size(RenoirRegionHandle handle);

/**
 * Get region name
 */
char *renoir_region_name(RenoirRegionHandle handle);

/**
 * Open existing region by name
 */
enum RenoirErrorCode renoir_region_open(RenoirManagerHandle manager,
                                        const char *name,
                                        RenoirRegionHandle *region_handle);

/**
 * Close region handle (decreases reference count)
 */
enum RenoirErrorCode renoir_region_close(RenoirRegionHandle handle);

/**
 * Destroy region (admin operation - removes from all processes)
 */
enum RenoirErrorCode renoir_region_destroy(RenoirManagerHandle manager, const char *name);

/**
 * Get region statistics
 */
enum RenoirErrorCode renoir_region_stats(RenoirRegionHandle handle,
                                         struct RenoirRegionStats *stats);

